<template>
<section class="clubs-overview">
 <h3 class="page-title">Clubes</h3><div class="text-end mb-3"><button v-if="canManage" class="btn btn-primary" @click="$refs.gestor.openModal()">Agregar club</button></div><p v-if="mensaje" class="alert alert-info" role="status">{{ mensaje }}</p>
 <div class="period-banner"><strong>{{ periodoActivo?.nombre || 'Sin periodo activo' }}</strong><span v-if="periodoActivo">{{ fecha(periodoActivo.fecha_inicio) }} — {{ fecha(periodoActivo.fecha_fin) }}</span></div>
 <section class="weekly-schedule"><h4>Horario común de los clubes</h4><p v-if="horario.dias.length===2">{{ horario.dias.join(' y ') }} · {{ horario.inicio }} a {{ horario.fin }}</p><p v-else class="text-muted">Todavía no se ha configurado el horario semanal.</p><details v-if="canManage"><summary>Configurar días y horario</summary><form @submit.prevent="guardarHorario"><p class="small mt-3">Selecciona exactamente dos días. Este horario se aplica a todos los clubes.</p><div class="days-grid"><label v-for="d in diasSemana" :key="d"><input type="checkbox" v-model="horarioBorrador.dias" :value="d" :disabled="horarioBorrador.dias.length===2 && !horarioBorrador.dias.includes(d)"> {{ d }}</label></div><div class="row g-3 my-2"><label class="col-sm-6">Hora de inicio<input type="time" required v-model="horarioBorrador.inicio" class="form-control"></label><label class="col-sm-6">Hora de término<input type="time" required v-model="horarioBorrador.fin" class="form-control"></label></div><button class="btn btn-primary" :disabled="guardandoHorario || cargandoLugares">Guardar horario común</button></form></details></section>
 <div class="club-totals"><div><strong>{{ clubs.length }}</strong><span>Clubes</span></div><div><strong>{{ totalAlumnos }}</strong><span>Alumnos inscritos</span></div><div><strong>{{ totalMonitores }}</strong><span>Monitores asignados</span></div></div>
 <p v-if="!clubs.length" class="text-muted text-center">No hay clubes registrados.</p>
 <div class="club-grid"><article v-for="c in ordenados" :key="c.id" class="club-information">
 <header><span class="category">{{ c.tipo === 'DEPORTIVO' ? 'Deportivo' : 'Cultural' }}</span><h4>{{ c.nombre }}</h4><p>{{ c.descripcion || 'Sin descripción registrada.' }}</p><div v-if="canManage" class="d-flex gap-2 mt-3"><button class="btn btn-sm btn-outline-primary" @click="$refs.gestor.startEdit(c)"><i class="bi bi-pencil-square me-1"></i>Editar</button><button class="btn btn-sm btn-outline-danger" @click="$refs.gestor.confirmDelete(c)"><i class="bi bi-trash me-1"></i>Eliminar</button></div></header>
 <div class="club-people"><div><small>{{ c.monitores?.length>1 ? 'Monitores responsables' : 'Monitor responsable' }}</small><span v-if="!c.monitores?.length">Sin monitor asignado</span><div v-for="m in c.monitores || []" :key="m.id"><strong>{{ nombre(m) }}</strong><span v-if="m.usuario">Usuario: {{ m.usuario }}</span></div></div></div>
 <div class="club-location"><small>Lugar por día</small><div v-for="dia in horario.dias" :key="dia" class="day-place"><strong>{{ dia }} · {{ horario.inicio }}–{{ horario.fin }}</strong><p>{{ lugaresDia[c.id]?.[dia] || ubicaciones[c.id] || 'Sin lugar configurado' }}</p></div><p v-if="!horario.dias.length">Configura primero los dos días comunes.</p><details v-if="canManage && horario.dias.length===2"><summary>Configurar lugares de este club</summary><form @submit.prevent="guardarLugar(c)"><label v-for="dia in horario.dias" :key="dia" class="form-label d-block mt-3">{{ dia }}<input v-model="borradoresDia[c.id+'_'+dia]" class="form-control" required maxlength="250" spellcheck="true" lang="es" autocorrect="on" autocomplete="on" list="lugares-sugeridos" placeholder="Ej. Cancha techada, edificio B, aula 3"></label><button class="btn btn-sm btn-primary mt-2" :disabled="guardando!==null || cargandoLugares">{{ guardando===c.id ? 'Guardando…' : 'Guardar lugares' }}</button></form></details></div>
 <p class="club-period">Periodo: {{ periodoActivo?.nombre || 'Sin periodo activo' }}</p>
 <div class="occupancy"><span><strong>{{ Number(c.ocupados || 0) }}</strong> alumnos</span><span>Cupo: {{ Number(c.cupo || 0) }}</span></div>
 <label :for="'progreso-club-'+c.id">Ocupación del cupo · {{ porcentaje(c) }}%</label><progress :id="'progreso-club-'+c.id" :value="Math.min(porcentaje(c),100)" max="100"></progress>
 <small>{{ Number(c.ocupados || 0)>Number(c.cupo || 0) ? 'El número de inscritos supera el cupo.' : Math.max(0,Number(c.cupo || 0)-Number(c.ocupados || 0))+' lugares disponibles' }}</small>
 </article></div>
<datalist id="lugares-sugeridos"><option v-for="l in sugerenciasLugares" :key="l" :value="l" /></datalist>
<ClubsR ref="gestor" :clubs="clubs" :can-manage="canManage" modal-only @add-club="(...args)=>$emit('add-club',...args)" @edit-club="(...args)=>$emit('edit-club',...args)" @delete-club="(...args)=>$emit('delete-club',...args)" @refresh="$emit('refresh')" @show-error="$emit('show-error',$event)" />
</section>
</template>
<script>
import ClubsR from './ClubsR.vue';
import api from '../servicios/cliente-http';
export default {
 components:{ClubsR},emits:["add-club","edit-club","delete-club","refresh","show-error"],
 data:()=>({horario:{dias:[],inicio:"",fin:""},horarioBorrador:{dias:[],inicio:"",fin:""},diasSemana:["Lunes","Martes","Miércoles","Jueves","Viernes","Sábado","Domingo"],lugaresDia:{},borradoresDia:{},guardandoHorario:false,mensajeTimer:null,ubicaciones:{},borradores:{},mensaje:"",guardando:null,cargandoLugares:true}),
 async mounted(){try{const {data}=await api.get('/config');for(const r of data.data || []){if(r.clave==='clubs_horario_semanal'){const h=JSON.parse(r.valor);this.horario=h;this.horarioBorrador={...h,dias:[...h.dias]};}else if(r.clave.startsWith('club_lugares_')){const id=r.clave.slice(13);const lugares=JSON.parse(r.valor);this.lugaresDia[id]=lugares;for(const [dia,lugar] of Object.entries(lugares))this.borradoresDia[id+'_'+dia]=lugar;}else if(r.clave.startsWith('club_ubicacion_'))this.ubicaciones[r.clave.slice(15)]=r.valor;}}catch(e){this.avisar('No se pudo cargar la configuración semanal.');}finally{this.cargandoLugares=false;}},
 beforeUnmount(){clearTimeout(this.mensajeTimer);},
 props:{canManage:Boolean,clubs:{type:Array,default:()=>[]},usuarios:{type:Array,default:()=>[]},periodoActivo:{type:Object,default:null}},
 computed:{sugerenciasLugares(){return [...new Set(["Cancha techada","Auditorio","Biblioteca","Laboratorio de cómputo","Sala de usos múltiples",...Object.values(this.ubicaciones),...Object.values(this.lugaresDia).flatMap(v=>Object.values(v))])].filter(Boolean);},ordenados(){return [...this.clubs].sort((a,b)=>a.nombre.localeCompare(b.nombre,'es'));},totalAlumnos(){return this.clubs.reduce((n,c)=>n+Number(c.ocupados || 0),0);},totalMonitores(){return new Set(this.clubs.flatMap(c=>(c.monitores || []).map(m=>m.id))).size;}},
 methods:{avisar(texto){clearTimeout(this.mensajeTimer);this.mensaje=texto;this.mensajeTimer=setTimeout(()=>this.mensaje='',6500);},
 async guardarHorario(){if(!this.canManage||this.guardandoHorario)return;const h=this.horarioBorrador;if(h.dias.length!==2||new Set(h.dias).size!==2||h.dias.some(d=>!this.diasSemana.includes(d))||!h.inicio||!h.fin||h.fin<=h.inicio){this.avisar('Selecciona dos días distintos y una hora de término posterior al inicio.');return;}this.guardandoHorario=true;try{const valor={dias:this.diasSemana.filter(d=>h.dias.includes(d)),inicio:h.inicio,fin:h.fin};await api.post('/config',{clave:'clubs_horario_semanal',valor:JSON.stringify(valor)});this.horario=valor;this.avisar('Horario común guardado para todos los clubes.');}catch(e){this.avisar(e.response?.data?.statusMessage || 'No se pudo guardar el horario.');}finally{this.guardandoHorario=false;}},
 async guardarLugar(c){if(!this.canManage || this.guardando!==null)return;const valor=Object.fromEntries(this.horario.dias.map(d=>[d,(this.borradoresDia[c.id+'_'+d] || '').trim()]));if(this.horario.dias.length!==2 || Object.values(valor).some(v=>!v)){this.avisar('Indica el lugar para los dos días.');return;}this.guardando=c.id;try{await api.post('/config',{clave:'club_lugares_'+c.id,valor:JSON.stringify({...this.lugaresDia[c.id],...valor})});this.lugaresDia[c.id]={...this.lugaresDia[c.id],...valor};this.avisar('Lugares guardados para '+c.nombre+'.');}catch(e){this.avisar(e.response?.data?.statusMessage || 'No se pudieron guardar los lugares.');}finally{this.guardando=null;}},nombre(u){return [u.nombre,u.apellidoP,u.apellidoM].filter(Boolean).join(' ');},responsable(c){return [...this.usuarios,...(c.monitores || [])].find(u=>Number(u.id)===Number(c.id_responsable));},porcentaje(c){return Number(c.cupo)>0?Math.round(Number(c.ocupados || 0)/Number(c.cupo)*100):0;},fecha(v){if(!v)return 'Sin fecha';const d=new Date(String(v).slice(0,10)+'T12:00:00');return Number.isNaN(d.getTime())?'Sin fecha':d.toLocaleDateString('es-MX');}}
};
</script>
<style scoped>
.period-banner{display:flex;justify-content:center;align-items:center;flex-wrap:wrap;gap:14px;background:#e6efff;border:1px solid #d6e3fa;border-radius:18px;padding:18px;color:#254779;margin:22px 0}.period-banner span{font-size:.85rem}.club-totals{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:24px}.club-totals>div{display:flex;flex-direction:column;align-items:center;background:#ffffffc9;border-radius:18px;padding:18px;border:1px solid white}.club-totals strong{font-size:1.7rem;color:#245adb}.club-totals span{color:#617694;font-size:.85rem}.club-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,340px),1fr));gap:22px}.club-information{background:#fff;border:1px solid #e0e9f8;border-radius:24px;padding:24px;box-shadow:0 8px 24px #2547790a}.category{display:inline-block;background:#e8f0ff;color:#3160ae;border-radius:20px;font-size:.72rem;padding:5px 10px;margin-bottom:10px}.club-information h4{margin-bottom:10px}.club-information header p{color:#64748b;font-size:.85rem}.club-people{display:grid;gap:16px;border-block:1px solid #e6edf8;padding:16px 0}.club-people strong,.club-people span,.club-people small{display:block}.club-people small{color:#6e829e;text-transform:uppercase;font-size:.65rem;letter-spacing:.08em;margin-bottom:5px}.club-people strong{font-size:.9rem;color:#243e64}.club-people span{font-size:.8rem;color:#637997}.club-period{font-size:.8rem;margin-top:16px;color:#456187}.occupancy{display:flex;justify-content:space-between;margin:16px 0 10px}.club-information label,.club-information>small{font-size:.75rem;color:#64748b}progress{display:block;width:100%;height:9px;border:0;border-radius:8px;overflow:hidden;margin:8px 0 12px;accent-color:#3472e9}progress::-webkit-progress-bar{background:#e6edf8}progress::-webkit-progress-value{background:linear-gradient(90deg,#168df0,#314bea)}@media(max-width:520px){.club-totals{gap:8px}.club-totals>div{padding:12px 6px}.club-totals span{text-align:center;font-size:.7rem}}
</style>

<style scoped>.club-location{margin-top:16px;padding:14px;background:#edf4ff;border-radius:14px}.club-location>small{color:#597299;text-transform:uppercase;font-size:.65rem;letter-spacing:.07em}.club-location p{margin:5px 0 10px;color:#243e64}.club-location summary{color:#2865d9;font-size:.8rem;cursor:pointer}</style>
<style scoped>.weekly-schedule{padding:22px;background:#f5f9ff;border:1px solid #d7e4fa;border-radius:22px;margin-bottom:22px}.weekly-schedule summary{color:#2f63bd;cursor:pointer}.days-grid{display:flex;flex-wrap:wrap;gap:12px}.days-grid label{background:white;border:1px solid #d5e3f7;padding:10px 14px;border-radius:12px}.day-place{margin-top:12px}.day-place strong{font-size:.8rem;color:#34577f}.day-place p{font-size:.85rem}</style>